import{_ as e,c as i,o as s,ag as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/faq.md","filePath":"es/guide/faq.md","lastUpdated":1794112334000}'),o={name:"es/guide/faq.md"};function r(t,a,c,l,d,u){return s(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><h2 id="preguntas-generales" tabindex="-1">Preguntas generales <a class="header-anchor" href="#preguntas-generales" aria-label="Permalink to &quot;Preguntas generales&quot;">​</a></h2><h3 id="¿que-es-nicasa" tabindex="-1">¿Qué es Nicasa? <a class="header-anchor" href="#¿que-es-nicasa" aria-label="Permalink to &quot;¿Qué es Nicasa?&quot;">​</a></h3><p>Nicasa es un visor de imágenes de escritorio moderno y una herramienta de captura de pantalla diseñada exclusivamente para macOS. Ofrece una navegación rápida e intuitiva por tus colecciones de imágenes con una interfaz limpia y ágil, además de potentes capacidades de edición con IA.</p><h3 id="¿nicasa-es-gratis" tabindex="-1">¿Nicasa es gratis? <a class="header-anchor" href="#¿nicasa-es-gratis" aria-label="Permalink to &quot;¿Nicasa es gratis?&quot;">​</a></h3><p>La extensión de Chrome es totalmente gratuita. La app para macOS requiere una compra única de 4,99 $ para acceder a todas las funciones.</p><h3 id="¿que-sistemas-operativos-son-compatibles" tabindex="-1">¿Qué sistemas operativos son compatibles? <a class="header-anchor" href="#¿que-sistemas-operativos-son-compatibles" aria-label="Permalink to &quot;¿Qué sistemas operativos son compatibles?&quot;">​</a></h3><p>Actualmente Nicasa solo está disponible para macOS 10.13 o posterior. Por el momento no hay versiones para Windows ni Linux.</p><h3 id="¿como-actualizo-nicasa" tabindex="-1">¿Cómo actualizo Nicasa? <a class="header-anchor" href="#¿como-actualizo-nicasa" aria-label="Permalink to &quot;¿Cómo actualizo Nicasa?&quot;">​</a></h3><p>Las actualizaciones se gestionan a través del Mac App Store. Recibirás notificaciones cuando haya actualizaciones disponibles y podrás actualizar directamente desde la app App Store.</p><h2 id="preguntas-de-uso" tabindex="-1">Preguntas de uso <a class="header-anchor" href="#preguntas-de-uso" aria-label="Permalink to &quot;Preguntas de uso&quot;">​</a></h2><h3 id="¿como-hago-capturas-de-pantalla-con-nicasa" tabindex="-1">¿Cómo hago capturas de pantalla con Nicasa? <a class="header-anchor" href="#¿como-hago-capturas-de-pantalla-con-nicasa" aria-label="Permalink to &quot;¿Cómo hago capturas de pantalla con Nicasa?&quot;">​</a></h3><ol><li>Abre Nicasa</li><li>Haz clic en el botón de captura de la barra de herramientas o usa <code>Cmd+S</code></li><li>Selecciona el área que quieres capturar</li><li>La captura se abrirá en Nicasa para editarla de inmediato</li></ol><h3 id="¿nicasa-funciona-con-imagenes-web" tabindex="-1">¿Nicasa funciona con imágenes web? <a class="header-anchor" href="#¿nicasa-funciona-con-imagenes-web" aria-label="Permalink to &quot;¿Nicasa funciona con imágenes web?&quot;">​</a></h3><p>¡Sí! Instala la extensión de Chrome gratuita de Nicasa para:</p><ul><li>Ver todas las imágenes de cualquier sitio web en un solo lugar</li><li>Extraer y explorar imágenes al instante</li><li>Abrir imágenes directamente en Nicasa para una mejor visualización</li></ul><h3 id="¿que-funciones-de-edicion-con-ia-hay-disponibles" tabindex="-1">¿Qué funciones de edición con IA hay disponibles? <a class="header-anchor" href="#¿que-funciones-de-edicion-con-ia-hay-disponibles" aria-label="Permalink to &quot;¿Qué funciones de edición con IA hay disponibles?&quot;">​</a></h3><p>Nicasa incluye potentes herramientas de IA:</p><ul><li><strong>Mejora automática</strong>: mejora la calidad de la imagen automáticamente</li><li><strong>Recorte inteligente</strong>: sugerencias inteligentes de recorte</li><li><strong>Relleno</strong>: elimina objetos no deseados de forma inteligente</li><li><strong>Corrección de color</strong>: ajustes de color impulsados por IA</li><li><strong>Reducción de ruido</strong>: elimina el ruido y el grano</li></ul><h3 id="¿como-funciona-el-modo-superposicion-transparente" tabindex="-1">¿Cómo funciona el modo superposición transparente? <a class="header-anchor" href="#¿como-funciona-el-modo-superposicion-transparente" aria-label="Permalink to &quot;¿Cómo funciona el modo superposición transparente?&quot;">​</a></h3><p>Perfecto para diseñadores y artistas:</p><ul><li>Fija imágenes por encima de todas las ventanas con transparencia ajustable</li><li>Úsalo para calcar, consultar referencias o comparar interfaces</li><li>Mantiene la posición en todas las aplicaciones</li></ul><h2 id="preguntas-tecnicas" tabindex="-1">Preguntas técnicas <a class="header-anchor" href="#preguntas-tecnicas" aria-label="Permalink to &quot;Preguntas técnicas&quot;">​</a></h2><h3 id="¿por-que-necesito-conceder-el-permiso-de-grabacion-de-pantalla" tabindex="-1">¿Por qué necesito conceder el permiso de grabación de pantalla? <a class="header-anchor" href="#¿por-que-necesito-conceder-el-permiso-de-grabacion-de-pantalla" aria-label="Permalink to &quot;¿Por qué necesito conceder el permiso de grabación de pantalla?&quot;">​</a></h3><p>El permiso de grabación de pantalla es necesario para la función de captura. Permite a Nicasa capturar tu pantalla cuando usas la herramienta de captura.</p><h3 id="¿puedo-usar-nicasa-sin-conexion" tabindex="-1">¿Puedo usar Nicasa sin conexión? <a class="header-anchor" href="#¿puedo-usar-nicasa-sin-conexion" aria-label="Permalink to &quot;¿Puedo usar Nicasa sin conexión?&quot;">​</a></h3><p>Sí. La app para macOS funciona completamente sin conexión con archivos de imagen locales. La extracción de imágenes web mediante la extensión de Chrome requiere conexión a internet.</p><h3 id="¿que-versiones-de-macos-son-compatibles" tabindex="-1">¿Qué versiones de macOS son compatibles? <a class="header-anchor" href="#¿que-versiones-de-macos-son-compatibles" aria-label="Permalink to &quot;¿Qué versiones de macOS son compatibles?&quot;">​</a></h3><p>Nicasa es compatible con macOS 10.13 o posterior. Está optimizada para Apple Silicon y se ejecuta de forma nativa en chips de la serie M.</p><h3 id="¿que-permisos-necesita-la-extension-de-chrome" tabindex="-1">¿Qué permisos necesita la extensión de Chrome? <a class="header-anchor" href="#¿que-permisos-necesita-la-extension-de-chrome" aria-label="Permalink to &quot;¿Qué permisos necesita la extensión de Chrome?&quot;">​</a></h3><p>La extensión solicita acceso al contenido de la página únicamente para extraer las URL de las imágenes. No lee ni almacena el historial de navegación.</p><h3 id="¿se-suben-mis-datos-a-algun-lugar" tabindex="-1">¿Se suben mis datos a algún lugar? <a class="header-anchor" href="#¿se-suben-mis-datos-a-algun-lugar" aria-label="Permalink to &quot;¿Se suben mis datos a algún lugar?&quot;">​</a></h3><p>No. Todo el procesamiento ocurre localmente en tu dispositivo. Nicasa no recopila, transmite ni almacena tus imágenes.</p><h3 id="¿como-hago-una-copia-de-seguridad-de-mis-ajustes" tabindex="-1">¿Cómo hago una copia de seguridad de mis ajustes? <a class="header-anchor" href="#¿como-hago-una-copia-de-seguridad-de-mis-ajustes" aria-label="Permalink to &quot;¿Cómo hago una copia de seguridad de mis ajustes?&quot;">​</a></h3><p>Tus ajustes se guardan localmente. Para hacer una copia de seguridad:</p><ol><li>Ve a Nicasa &gt; Preferencias</li><li>Exporta tus ajustes si está disponible</li><li>O haz una copia manual de la carpeta de preferencias de la aplicación</li></ol><p>Los ajustes se guardan en la carpeta de datos de la aplicación. Copia esa carpeta para respaldar tus preferencias.</p><h3 id="¿existe-una-version-portatil" tabindex="-1">¿Existe una versión portátil? <a class="header-anchor" href="#¿existe-una-version-portatil" aria-label="Permalink to &quot;¿Existe una versión portátil?&quot;">​</a></h3><p>Hay una versión portátil disponible para Windows. Descárgala desde nuestro sitio web.</p><h2 id="preguntas-de-desarrollo" tabindex="-1">Preguntas de desarrollo <a class="header-anchor" href="#preguntas-de-desarrollo" aria-label="Permalink to &quot;Preguntas de desarrollo&quot;">​</a></h2><h3 id="¿puedo-contribuir-a-nicasa" tabindex="-1">¿Puedo contribuir a Nicasa? <a class="header-anchor" href="#¿puedo-contribuir-a-nicasa" aria-label="Permalink to &quot;¿Puedo contribuir a Nicasa?&quot;">​</a></h3><p>Visita nuestro <a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">repositorio de GitHub</a> para contribuir con código, informar de problemas o sugerir funciones.</p><h3 id="¿como-compilo-nicasa-desde-el-codigo-fuente" tabindex="-1">¿Cómo compilo Nicasa desde el código fuente? <a class="header-anchor" href="#¿como-compilo-nicasa-desde-el-codigo-fuente" aria-label="Permalink to &quot;¿Cómo compilo Nicasa desde el código fuente?&quot;">​</a></h3><p>Consulta nuestra documentación para desarrolladores en GitHub para obtener las instrucciones de compilación.</p><h3 id="¿que-tecnologias-usa-nicasa" tabindex="-1">¿Qué tecnologías usa Nicasa? <a class="header-anchor" href="#¿que-tecnologias-usa-nicasa" aria-label="Permalink to &quot;¿Qué tecnologías usa Nicasa?&quot;">​</a></h3><p>Nicasa está creada con tecnologías web modernas, incluido Electron para el contenedor de escritorio y Vue.js para la interfaz.</p><h2 id="preguntas-de-privacidad" tabindex="-1">Preguntas de privacidad <a class="header-anchor" href="#preguntas-de-privacidad" aria-label="Permalink to &quot;Preguntas de privacidad&quot;">​</a></h2><h3 id="¿nicasa-recopila-algun-dato" tabindex="-1">¿Nicasa recopila algún dato? <a class="header-anchor" href="#¿nicasa-recopila-algun-dato" aria-label="Permalink to &quot;¿Nicasa recopila algún dato?&quot;">​</a></h3><p>No, Nicasa no recopila ni transmite ningún dato personal. Todo el procesamiento de imágenes ocurre localmente en tu dispositivo.</p><h3 id="¿mis-imagenes-estan-seguras" tabindex="-1">¿Mis imágenes están seguras? <a class="header-anchor" href="#¿mis-imagenes-estan-seguras" aria-label="Permalink to &quot;¿Mis imágenes están seguras?&quot;">​</a></h3><p>Sí. Nicasa solo accede a las imágenes que abres explícitamente. No sube ni comparte tus archivos.</p><h3 id="¿que-permisos-necesita-nicasa" tabindex="-1">¿Qué permisos necesita Nicasa? <a class="header-anchor" href="#¿que-permisos-necesita-nicasa" aria-label="Permalink to &quot;¿Qué permisos necesita Nicasa?&quot;">​</a></h3><p>Nicasa necesita acceso al sistema de archivos para leer imágenes y guardar ajustes. No requiere conexión a internet para funcionar.</p><h2 id="¿aun-tienes-dudas" tabindex="-1">¿Aún tienes dudas? <a class="header-anchor" href="#¿aun-tienes-dudas" aria-label="Permalink to &quot;¿Aún tienes dudas?&quot;">​</a></h2><p>Si no encuentras la respuesta aquí:</p><ol><li>Consulta nuestra <a href="/es/">documentación completa</a></li><li>Busca en nuestras <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">incidencias de GitHub</a></li><li>Crea una nueva incidencia si es necesario</li></ol><p>¡Estamos aquí para ayudar!</p>',57)])])}const h=e(o,[["render",r]]);export{m as __pageData,h as default};
